20	func TestWatchShouldSpend(t *testing.T) {
21		now := time.Date(2026, 6, 7, 12, 0, 0, 0, time.UTC)
22		hourAgo := now.Add(-time.Hour)
23		cases := []struct {
24			name    string
25			w       watchCommandOptions
26			cursor  watchCursor
27			spent   int
28			wantRun bool
29		}{
30			{"all disabled", watchCommandOptions{distill: false, seedAgent: "none", distillEvery: time.Hour}, watchCursor{}, 0, false},
31			{"distill first run", watchCommandOptions{distill: true, seedAgent: "none", distillEvery: time.Hour}, watchCursor{}, 0, true},
32			// --seed-agent alone is gated identically to --distill (the invariant the fix protects).
33			{"seed-agent enabled, first run", watchCommandOptions{distill: false, seedAgent: "codex", distillEvery: time.Hour}, watchCursor{}, 0, true},
34			{"seed-agent enabled, interval not elapsed", watchCommandOptions{distill: false, seedAgent: "codex", distillEvery: time.Hour}, watchCursor{LastAgentSpendAt: now.Add(-30 * time.Minute)}, 0, false},
35			{"interval not elapsed", watchCommandOptions{distill: true, distillEvery: time.Hour}, watchCursor{LastAgentSpendAt: now.Add(-30 * time.Minute)}, 0, false},
36			{"interval elapsed", watchCommandOptions{distill: true, distillEvery: time.Hour}, watchCursor{LastAgentSpendAt: hourAgo}, 0, true},
37			{"budget reached (seed)", watchCommandOptions{seedAgent: "codex", distillEvery: 0, budget: 1}, watchCursor{}, 1, false},
38			{"budget not reached", watchCommandOptions{distill: true, distillEvery: 0, budget: 2}, watchCursor{}, 1, true},
39		}
40		for _, tc := range cases {
41			if got, _ := watchShouldSpend(tc.w, tc.cursor, tc.spent, now); got != tc.wantRun {
42				t.Errorf("%s: shouldSpend = %v, want %v", tc.name, got, tc.wantRun)
43			}
44		}
45	}
