17	// A long-running daemon outlives the binary it was started from; the probe is
18	// what lets it notice and hand itself back to the service manager (COR-2174).
19	func TestWatchBinaryChangeProbeDetectsReplacement(t *testing.T) {
20		path := filepath.Join(t.TempDir(), "entire-brain")
21		if err := os.WriteFile(path, []byte("build A"), 0o755); err != nil {
22			t.Fatal(err)
23		}
24		probe := watchBinaryChangeProbe(path)
25		if probe == nil {
26			t.Fatal("probe must exist for a readable binary")
27		}
28		if probe() {
29			t.Fatal("unchanged binary reported as replaced")
30		}
31	
32		// In-place rewrite (same inode, new mtime): the nightly `go build` case.
33		if err := os.WriteFile(path, []byte("build B"), 0o755); err != nil {
34			t.Fatal(err)
35		}
36		if err := os.Chtimes(path, time.Now(), time.Now().Add(time.Second)); err != nil {
37			t.Fatal(err)
38		}
39		if !probe() {
40			t.Fatal("rewritten binary not reported as replaced")
41		}
42	
43		// Atomic replacement (new inode): the install-by-rename case.
44		fresh := watchBinaryChangeProbe(path)
45		replacement := filepath.Join(t.TempDir(), "next")
46		if err := os.WriteFile(replacement, []byte("build C!"), 0o755); err != nil {
47			t.Fatal(err)
48		}
49		if err := os.Rename(replacement, path); err != nil {
50			t.Fatal(err)
51		}
52		if !fresh() {
53			t.Fatal("renamed-over binary not reported as replaced")
54		}
55	
56		// A vanished binary (mid-replace) must not trigger a restart onto nothing.
57		if err := os.Remove(path); err != nil {
58			t.Fatal(err)
59		}
60		if fresh() {
61			t.Fatal("a missing binary must defer the decision, not restart")
62		}
63	
64		if watchBinaryChangeProbe(filepath.Join(t.TempDir(), "absent")) != nil {
65			t.Fatal("an unreadable binary must disable the probe")
66		}
67	}
