75			t.Fatal(err)
76		}
77		out := &bytes.Buffer{}
78		passes := 0
79		err := supervisedWatchLoop(context.Background(), out, f.env, defaultWatchOptions(),
80			func(string, watchCommandOptions, *int) error { passes++; return nil },
81			nil, func() bool { return true })
82		if !errors.Is(err, errWatchBinaryReplaced) {
83			t.Fatalf("a replaced binary must end the loop with its sentinel, got %v", err)
84		}
