100		plan, err := planBrainWatchDaemon("darwin", home, "", "", spec)
101		if err != nil {
102			t.Fatal(err)
103		}
104		dead := &scriptedListRunner{listOutput: "{\n\t\"LastExitStatus\" = 0;\n}\n"}
105		running, detail := daemonRunning(context.Background(), dead, plan)
106		if running {
107			t.Fatal("a registered-but-dead job must not report as running")
108		}
109		if detail == "" {
110			t.Fatal("the registered-but-dead state must be named, not silent")
111		}
112		live := &scriptedListRunner{listOutput: "{\n\t\"PID\" = 123;\n}\n"}
