118	// The re-register child must repair the registration under the shared lock —
119	// but only while the unit still exists: a concurrent `setup --uninstall-daemon`
120	// removing the unit means the user declined the watcher, and re-registering it
121	// would resurrect what they just removed.
122	func TestDaemonReregisterRespectsUninstall(t *testing.T) {
123		f := newSetupTestFixture(t)
124		t.Setenv(envDaemonNoRegister, "")
125		runner := &recordingDaemonRunner{}
126		opts := f.opts
127		opts.Runner = runner
128	
129		plan, err := installedDaemonUnitPlan(opts)
130		if err != nil {
131			t.Fatalf("plan: %v", err)
132		}
133		if err := runDaemonReregister(context.Background(), io.Discard, opts); err != nil {
134			t.Fatalf("reregister with no unit installed: %v", err)
135		}
136		if len(runner.calls) != 0 {
137			t.Fatalf("no unit on disk, but the service manager was touched: %v", runner.calls)
138		}
139	
140		if !plan.supported() {
141			// windows: no service manager, so the calm no-op above is the whole
142			// contract — there is no unit to write and nothing to re-register.
143			return
144		}
145		if err := os.MkdirAll(filepath.Dir(plan.UnitPath), 0o755); err != nil {
146			t.Fatal(err)
147		}
148		if err := brainstore.WriteFileAtomic(plan.UnitPath, []byte(plan.Contents), 0o600); err != nil {
149			t.Fatal(err)
150		}
151		if err := runDaemonReregister(context.Background(), io.Discard, opts); err != nil {
152			t.Fatalf("reregister: %v", err)
153		}
154		// The plan resolves for the HOST service manager, so assert the verbs that
155		// manager uses: the CI matrix covers darwin and linux with one test.
156		verbs := []string{"launchctl bootout", "launchctl enable", "launchctl bootstrap"}
157		if plan.Manager == daemonManagerSystemd {
158			verbs = []string{"systemctl --user daemon-reload", "systemctl --user enable --now"}
159		}
160		got := strings.Join(runner.calls, "\n")
161		for _, verb := range verbs {
162			if !strings.Contains(got, verb) {
163				t.Fatalf("re-registration must run %q:\n%s", verb, got)
