224	// The writer's concurrency contract, stated as a test because the two things
225	// that keep it safe in this build are both implicit.
226	//
227	// watchLoop builds ONE of these and hands it to distill, refresh and seed as
228	// both stdout and stderr, and distill owns a --jobs worker pool. Nothing in
229	// this build writes to it from a second goroutine -- the workers return over
230	// channels, agent subprocesses get capped buffers, and the only progress
231	// goroutine is gated behind a TTY check that requires an *os.File, which this
232	// never is -- so this is not a regression test for an observed race. It is the
233	// guarantee that makes the sharing above safe to keep: every line comes out
234	// whole, stamped exactly once, whoever wrote it.
235	//
236	// Run under -race this fails without the lock; it also fails without it on
237	// content alone, because midLine is read and written on every call, so losing
238	// it mis-attributes continuation lines rather than crashing.
239	func TestWatchLogPrefixIsSafeForConcurrentWriters(t *testing.T) {
240		var sink lockedBuffer
241		w := newWatchLogPrefixWriter(&sink, testWatchLogFields("repo-a", nil), fixedClock(time.Unix(0, 0).UTC()))
242	
243		const writers, perWriter = 8, 40
244		var wg sync.WaitGroup
245		for id := 0; id < writers; id++ {
246			wg.Add(1)
247			go func(id int) {
248				defer wg.Done()
249				for n := 0; n < perWriter; n++ {
250					if _, err := fmt.Fprintf(w, "writer=%d line=%d\n", id, n); err != nil {
251						t.Errorf("write: %v", err)
252						return
253					}
254				}
255			}(id)
256		}
257		wg.Wait()
258	
259		const stamp = "1970-01-01T00:00:00Z pid=4242 build=0.2.0 repo=repo-a "
260		lines := strings.Split(strings.TrimSuffix(sink.String(), "\n"), "\n")
261		if len(lines) != writers*perWriter {
262			t.Fatalf("got %d lines, want %d; lines were interleaved or lost", len(lines), writers*perWriter)
263		}
264		seen := map[string]bool{}
265		for _, line := range lines {
266			if !strings.HasPrefix(line, stamp) {
267				t.Fatalf("line lost or doubled its stamp: %q", line)
268			}
269			body := strings.TrimPrefix(line, stamp)
270			if strings.Contains(body, "writer=") != true || strings.Contains(body, stamp) {
271				t.Fatalf("line body is not one whole write: %q", body)
272			}
273			if seen[body] {
274				t.Fatalf("duplicate line %q", body)
275			}
276			seen[body] = true
277		}
278		if len(seen) != writers*perWriter {
279			t.Fatalf("got %d distinct lines, want %d", len(seen), writers*perWriter)
280		}
281	}
282	
283	// lockedBuffer isolates what is under test: without it the SINK would be the
284	// race, and the test would pass or fail on bytes.Buffer's thread-safety rather
285	// than on the writer's.
286	type lockedBuffer struct {
287		mu  sync.Mutex
288		buf bytes.Buffer
289	}
290	
291	func (b *lockedBuffer) Write(p []byte) (int, error) {
292		b.mu.Lock()
293		defer b.mu.Unlock()
294		return b.buf.Write(p)
295	}
296	
297	func (b *lockedBuffer) String() string {
298		b.mu.Lock()
299		defer b.mu.Unlock()
300		return b.buf.String()
301	}
