172	// TestWatchLoopStampsTickLinesAndStepOutput is the single-repo half of
173	// COR-2176, driven through the real loop rather than the writer. Two things
174	// are guarded that the earlier attempt at this fix got wrong: the loop, not
175	// the tick, decides attribution (that attempt stamped only the banner printed
176	// above the loop, which was never the problem), and the STEPS write to the
177	// same attributed sink -- `refresh: seed baseline failed` is the line the
178	// ticket quotes, and it is written by the refresh step, not by the tick.
179	func TestWatchLoopStampsTickLinesAndStepOutput(t *testing.T) {
180		t.Parallel()
181		dir := t.TempDir()
182		cursor := filepath.Join(dir, "watch.json")
183		at := time.Date(2026, 10, 24, 9, 30, 15, 0, time.UTC)
184		var refreshed, seeded, distilled int
185		w := defaultWatchOptions()
186		w.once = true
187	
188		var buf bytes.Buffer
189		var sawSink bool
190		stepsFor := func(sink io.Writer) watchSteps {
191			sawSink = true
192			steps := fakeWatchSteps("ck1:head1", &refreshed, &seeded, &distilled)
193			inner := steps.refresh
194			steps.refresh = func(c context.Context) error {
195				// Stand in for watchDeterministicRefresh's progress reporter,
196				// which writes through the command it is handed.
197				fmt.Fprintln(sink, "refresh: seed baseline failed")
198				return inner(c)
199			}
200			return steps
201		}
202		if err := watchLoop(context.Background(), &buf, watchLogFields{pid: 4242, build: "0.2.0", repo: "gh/entireio/entire-brain"},
203			fixedClock(at), w, cursor, stepsFor); err != nil {
204			t.Fatalf("watchLoop: %v", err)
205		}
206		if !sawSink {
207			t.Fatalf("the loop never asked for steps bound to its sink")
208		}
209		out := buf.String()
210		if strings.TrimSpace(out) == "" {
211			t.Fatalf("tick wrote nothing; the guard would pass vacuously")
212		}
213		stamp := "2026-10-24T09:30:15Z pid=4242 build=0.2.0 tick=1 repo=gh/entireio/entire-brain "
214		for i, line := range strings.Split(strings.TrimSuffix(out, "\n"), "\n") {
215			if !strings.HasPrefix(line, stamp) {
216				t.Fatalf("tick line %d is unattributed: %q\nfull log:\n%s", i, line, out)
217			}
218		}
219		if !strings.Contains(out, stamp+"refresh: seed baseline failed") {
220			t.Fatalf("the refresh step's own line did not reach the attributed sink:\n%s", out)
221		}
222	}
