		// ModTime catches the in-place rebuild, Size catches an in-place copy
		// that preserved mtime (cp -p, rsync -t).
		return !os.SameFile(started, current) ||
			!current.ModTime().Equal(started.ModTime()) ||
			current.Size() != started.Size()
	}
}

